--
-- Table structure for table `log_report_user`
--

DROP TABLE IF EXISTS `log_report_user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `log_report_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `time_report` date NOT NULL,
  `nick_name` varchar(50) NOT NULL,
  `wm` bigint(20) DEFAULT NULL,
  `wm_win` bigint(20) DEFAULT NULL,
  `ibc` bigint(20) DEFAULT NULL,
  `ibc_win` bigint(20) DEFAULT NULL,
  `ag` bigint(20) DEFAULT NULL,
  `ag_win` bigint(20) DEFAULT NULL,
  `tlmn` bigint(20) DEFAULT NULL,
  `tlmn_win` bigint(20) DEFAULT NULL,
  `bacay` bigint(20) DEFAULT NULL,
  `bacay_win` bigint(20) DEFAULT NULL,
  `xocdia` bigint(20) DEFAULT NULL,
  `xocdia_win` bigint(20) DEFAULT NULL,
  `minipoker` bigint(20) DEFAULT NULL,
  `minipoker_win` bigint(20) DEFAULT NULL,
  `slot_pokemon` bigint(20) DEFAULT NULL,
  `slot_pokemon_win` bigint(20) DEFAULT NULL,
  `baucua` bigint(20) DEFAULT NULL,
  `baucua_win` bigint(20) DEFAULT NULL,
  `taixiu` bigint(20) DEFAULT NULL,
  `taixiu_win` bigint(20) DEFAULT NULL,
  `caothap` bigint(20) DEFAULT NULL,
  `caothap_win` bigint(20) DEFAULT NULL,
  `slot_bitcoin` bigint(20) DEFAULT NULL,
  `slot_bitcoin_win` bigint(20) DEFAULT NULL,
  `slot_taydu` bigint(20) DEFAULT NULL,
  `slot_taydu_win` bigint(20) DEFAULT NULL,
  `slot_angrybird` bigint(20) DEFAULT NULL,
  `slot_angrybird_win` bigint(20) DEFAULT NULL,
  `slot_thantai` bigint(20) DEFAULT NULL,
  `slot_thantai_win` bigint(20) DEFAULT NULL,
  `slot_thethao` bigint(20) DEFAULT NULL,
  `slot_thethao_win` bigint(20) DEFAULT NULL,
  `deposit` bigint(20) DEFAULT NULL,
  `withdraw` bigint(20) DEFAULT NULL,
  `t_bonus` bigint(20) DEFAULT NULL COMMENT 'tổng bonus',
  `cmd` bigint(20) DEFAULT NULL,
  `cmd_win` bigint(20) DEFAULT '0',
  `t_refund` bigint(20) DEFAULT '0' COMMENT 'tổng hoàn tiền chiết khấu',
  `code` varchar(80) DEFAULT NULL COMMENT 'mã đại lý',
  `t_sport_bonus` bigint(20) DEFAULT NULL,
  `t_casino_bonus` bigint(20) DEFAULT NULL,
  `t_egame_bonus` bigint(20) DEFAULT NULL,
  `slot_chiemtinh` bigint(20) DEFAULT '0',
  `slot_chiemtinh_win` bigint(20) DEFAULT NULL,
  `taixiu_st` bigint(20) DEFAULT NULL COMMENT 'tai xiu sieu toc',
  `taixiu_st_win` bigint(20) DEFAULT NULL,
  `fish` bigint(20) DEFAULT NULL COMMENT 'ban ca',
  `fish_win` bigint(20) DEFAULT NULL,
  `slot_thanbai` bigint(20) DEFAULT '0',
  `slot_thanbai_win` bigint(20) DEFAULT '0',
  `ebet` bigint(20) DEFAULT '0',
  `ebet_win` bigint(20) DEFAULT '0',
  `sbo` bigint(20) DEFAULT '0',
  `sbo_win` bigint(20) DEFAULT '0',
  `slot_bikini` bigint(20) DEFAULT '0',
  `slot_bikini_win` bigint(20) DEFAULT '0',
  `slot_galaxy` bigint(20) DEFAULT '0',
  `slot_galaxy_win` bigint(20) DEFAULT '0',
  `attendance` bigint(20) DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `nickname_time` (`nick_name`,`time_report`) USING BTREE,
  KEY `idx_nickname` (`nick_name`) USING BTREE COMMENT 'index',
  KEY `idx_time_report` (`time_report`) USING BTREE COMMENT 'index time_report'
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8;
