-- Table structure for table `log_tranfer_agent`
--

DROP TABLE IF EXISTS `log_tranfer_agent`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `log_tranfer_agent` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `transaction_no` varchar(45) NOT NULL,
  `agent_level1` varchar(45) DEFAULT NULL,
  `nick_name_send` varchar(45) DEFAULT NULL,
  `nick_name_receive` varchar(45) DEFAULT NULL,
  `money_send` bigint(20) DEFAULT NULL,
  `money_receive` bigint(20) DEFAULT NULL,
  `status` int(11) DEFAULT NULL,
  `fee` bigint(20) DEFAULT NULL,
  `top_ds` int(11) DEFAULT NULL,
  `process` int(11) DEFAULT NULL,
  `ti_gia` int(11) DEFAULT NULL,
  `is_freeze_money` int(11) DEFAULT NULL,
  `des_send` varchar(500) DEFAULT NULL,
  `des_receive` varchar(500) DEFAULT NULL,
  `session_id_freeze_money` varchar(45) DEFAULT NULL,
  `trans_time` varchar(45) DEFAULT NULL,
  `update_time` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `transaction_no_index` (`transaction_no`) USING BTREE,
  KEY `agent_level1_index` (`agent_level1`) USING BTREE,
  KEY `nick_name_send_index` (`nick_name_send`) USING BTREE,
  KEY `nick_name_receive_index` (`nick_name_receive`) USING BTREE,
  KEY `money_send_index` (`money_send`) USING BTREE,
  KEY `money_receive_index` (`money_receive`) USING BTREE,
  KEY `status_index` (`status`) USING BTREE,
  KEY `fee_index` (`fee`) USING BTREE,
  KEY `top_ds_index` (`top_ds`) USING BTREE,
