CREATE DEFINER=`root`@`%` FUNCTION `fn_GetSumDepositByNickname`(p_nickname VARCHAR(128),p_createtime datetime, p_days int) RETURNS int(11)
BEGIN
	DECLARE result INT;
	SET result = 0;
	select SUM(deposit) into result from log_count_user_play where time_report >= p_createtime
								and time_report <= DATE_ADD(p_createtime, INTERVAL p_days DAY)
								and nick_name = p_nickname;
	if result is null THEN
		return 0;
	else
		return result;
	END IF;
END ;;
