CREATE DEFINER=`root`@`%` PROCEDURE `insert_bot`(IN p_un NVARCHAR(45),
IN p_nn NVARCHAR(45),
IN p_pw NVARCHAR(100),
IN p_vin BIGINT(20),
IN p_xu BIGINT(20),
IN p_status INT(11))
