	INSERT INTO users(user_name,nick_name,`password`,vin,vin_total,xu,xu_total,avatar,`status`,is_bot) VALUES(p_un,p_nn,p_pw,p_vin,p_vin,p_xu,p_xu,'0',p_status,1);
