CREATE TABLE `log_loginadmin` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(255) CHARACTER SET utf8 DEFAULT NULL,
  `nickname` varchar(255) CHARACTER SET utf8 DEFAULT NULL,
  `ip` varchar(255) CHARACTER SET utf8 DEFAULT NULL,
  `status` int(11) DEFAULT NULL,
  `agent` varchar(255) CHARACTER SET utf8 DEFAULT NULL,
  `action` varchar(255) CHARACTER SET utf8 DEFAULT NULL,
  `tool` varchar(255) CHARACTER SET utf8 DEFAULT NULL,
  `old_data` text,
  `request_data` text,
  `object` varchar(2000) DEFAULT NULL,
  `type` varchar(50) DEFAULT NULL,
  `createdate` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `nickname_index` (`nickname`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1917 DEFAULT CHARSET=latin1;
