CREATE DEFINER=`root`@`%` PROCEDURE `no_hu_game_bai`(IN p_session_id NVARCHAR(100),
IN p_user_id INT(11),
IN p_money_use BIGINT(20),
IN p_money_total BIGINT(20),
IN p_money_freeze BIGINT(20),
IN p_money_pot BIGINT(20),
IN p_pot_name NVARCHAR(45))
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION ROLLBACK;
  DECLARE EXIT HANDLER FOR SQLWARNING ROLLBACK;
  START TRANSACTION;
    UPDATE vinplay.users SET vin = p_money_use, vin_total = p_money_total WHERE id = p_user_id;
        UPDATE hu_game_bai SET `value` = p_money_pot WHERE `pot_name` = p_pot_name;   
    IF (p_money_freeze > -1) THEN
      UPDATE vinplay.freeze_money SET money = p_money_freeze WHERE session_id = p_session_id;
    END IF;
  COMMIT;
END ;;
DELIMITER ;
